$('resolved').onchange=()=>{const s=current();if(!s)return;const value=$('resolved').checked;commit(()=>{state.doc.resolved=state.doc.resolved.filter(id=>id!==s.id);if(value)state.doc.resolved.push(s.id);});};$('reviewed').onchange=()=>{if(!applyFieldsSafe()){$('reviewed').checked=state.doc.reviewed;return;}const value=$('reviewed').checked;commit(()=>state.doc.reviewed=value);};
$('undo').onclick=undo;$('redo').onclick=redo;for(const m of ['select','draw','pan'])$(m+'Mode').onclick=()=>setMode(m);$('fit').onclick=fit;$('zoomIn').onclick=()=>zoom(1.25);$('zoomOut').onclick=()=>zoom(.8);$('showBoxes').onchange=renderBoxes;$('problemOnly').onchange=()=>{state.problemOnly=$('problemOnly').checked;renderBoxes();};
$('canvas').addEventListener('pointerdown',down);$('canvas').addEventListener('pointermove',move);$('canvas').addEventListener('pointerup',up);$('canvas').addEventListener('pointercancel',()=>{if(state.drag){restore(state.drag.before);state.drag=null;render();}});$('canvas').addEventListener('wheel',e=>{e.preventDefault();const r=$('canvas').getBoundingClientRect();zoom(Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top);},{passive:false});
$('saveFile').onclick=saveFile;$('exportOpen').onclick=()=>{if(applyFieldsSafe())$('exportDialog').showModal();};$('downloadZip').onclick=()=>download('zip');$('downloadJson').onclick=()=>download('json');$('downloadXml').onclick=()=>download('xml');$('downloadReviewed').onclick=downloadReviewed;$('saveState').onclick=()=>flush();
window.addEventListener('keydown',e=>{const typing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable;if(e.key.toLowerCase()==='s'&&(e.ctrlKey||e.metaKey)){e.preventDefault();saveFile();return;}if(typing||$('exportDialog').open)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return;}if(e.code==='Space'){state.space=true;e.preventDefault();}if(e.key==='v')setMode('select');if(e.key==='b')setMode('draw');if(e.key==='h')setMode('pan');if(e.key==='Escape'){state.selected=null;render();}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}});window.addEventListener('keyup',e=>{if(e.code==='Space')state.space=false;});window.addEventListener('blur',()=>state.space=false);window.addEventListener('beforeunload',e=>{if(state.dirty||state.saving||pendingFields()){e.preventDefault();e.returnValue='';}});
function pendingFields(){const s=current();return !!s&&($('labelInput').value!==s.label||['x1','y1','x2','y2'].some((k,i)=>$(k).value.trim()===''||Number($(k).value)!==s.box[i]));}
document.querySelector('.discussion-link').onclick=async e=>{e.preventDefault();if(applyFieldsSafe()&&await flush())location.assign('fragments.html');};
let resizeTimer;new ResizeObserver(()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(!state.gallery&&!state.drag)fit();},150);}).observe($('canvas'));
async function init(){try{state.manifest=await api('/api/manifest');if(browserMode){document.querySelector('.library footer').textContent='草稿仅存此浏览器 · 下载结果交回';$('saveFile').textContent='下载当前标注包';}$('downloadReviewed').hidden=!browserMode;$('outputLocation').textContent='保存位置：'+state.manifest.outputPath+' · 导出版本 20260928.2';renderFiles();await openDoc(state.manifest.files[0].name);setMode('select');registerTools();}catch(e){status(browserMode?'读取失败，请刷新重试':'无法连接本地服务',true);tell(e.message,true);}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const tools=[{name:'silk_read_current_annotation',description:'读取当前图片、标注数量、选中框和复核状态。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>({name:state.doc.name,boxes:state.doc.shapes.length,selected:clone(current()||null),reviewed:state.doc.reviewed})},{name:'silk_select_annotation',description:'按当前序号选择并定位一个标注框，不修改数据。',inputSchema:{type:'object',properties:{index:{type:'integer',minimum:1}},required:['index'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!Number.isInteger(input.index)||input.index<1||input.index>state.doc.shapes.length)throw Error('标注序号超出范围');if(!applyFieldsSafe())throw Error('当前输入无效');choose(state.doc.shapes[input.index-1].id,true);return {name:state.doc.name,index:input.index,label:current().label};}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool)).catch(()=>{});}catch{}}
init();
